import { defineLesson } from '../define';
import type { ArrayState } from '../engines/array';
import type { ItemState } from '../engines/common';
import type { Frame } from '../types';

/*
 * Frames are generated by running the real algorithm, so every number on screen matches the notes.
 */

const NUMS = [2, 1, 5, 1, 3, 2];
const K = 3;

function range(from: number, to: number, st: ItemState): Record<number, ItemState> {
  const out: Record<number, ItemState> = {};
  for (let i = from; i <= to; i++) out[i] = st;
  return out;
}

/** Brute force: recompute every window from scratch, counting additions. */
function bruteFrames(): Frame<ArrayState>[] {
  const frames: Frame<ArrayState>[] = [];
  let adds = 0;
  for (let s = 0; s + K <= NUMS.length; s++) {
    let sum = 0;
    for (let j = s; j < s + K; j++) {
      sum += NUMS[j];
      adds++;
    }
    frames.push({
      hold: 1100,
      state: {
        rows: [{ cells: NUMS, states: range(s, s + K - 1, 'active'), window: { from: s, to: s + K - 1, label: `sum ${sum}` } }],
        stats: [
          { label: 'Window', value: `${s}..${s + K - 1}` },
          { label: 'Additions', value: String(adds), tone: s > 0 ? 'bad' : 'neutral', hint: 'n × k' },
          { label: 'Sum', value: String(sum) },
        ],
      },
    });
  }
  frames[frames.length - 1].state.note = { text: 'every window re-adds k numbers: O(n · k)', tone: 'bad' };
  return frames;
}

/** Fixed window: add the new element, record, remove the one falling off. */
function fixedFrames(): Frame<ArrayState>[] {
  const frames: Frame<ArrayState>[] = [];
  let sum = 0;
  let best = -Infinity;
  let bestAt = -1;
  let ops = 0;
  for (let i = 0; i < NUMS.length; i++) {
    sum += NUMS[i];
    ops++;
    const start = Math.max(0, i - K + 1);
    const full = i >= K - 1;
    if (full && sum > best) {
      best = sum;
      bestAt = start;
    }
    const states: Record<number, ItemState> = { ...range(0, start - 1, 'dim'), ...range(start, i, 'active') };
    frames.push({
      hold: 1000,
      state: {
        rows: [
          {
            cells: NUMS,
            states,
            window: { from: start, to: i, label: full ? `sum ${sum}` : `filling ${i + 1}/${K}`, tone: full && sum === best ? 'ok' : undefined },
            pointers: [
              { i: start, label: 'left', tone: 'info' },
              { i, label: 'right' },
            ],
          },
        ],
        stats: [
          { label: 'windowSum', value: String(sum) },
          { label: 'best', value: full ? String(best) : '-', tone: full ? 'ok' : 'neutral' },
          { label: 'Operations', value: String(ops), hint: 'one add, one remove each' },
        ],
      },
    });
    if (full) {
      sum -= NUMS[start];
      ops++;
    }
  }
  frames.push({
    state: {
      rows: [{ cells: NUMS, states: { ...range(0, NUMS.length - 1, 'dim'), ...range(bestAt, bestAt + K - 1, 'found') }, window: { from: bestAt, to: bestAt + K - 1, label: `best ${best}`, tone: 'ok' } }],
      stats: [
        { label: 'Answer', value: String(best), tone: 'ok' },
        { label: 'Window', value: `${bestAt}..${bestAt + K - 1}` },
        { label: 'Operations', value: String(ops), hint: 'about 2n' },
      ],
      note: { text: '5 + 1 + 3 = 9 in one pass', tone: 'ok' },
    },
  });
  return frames;
}

/** Variable window: longest substring without repeating characters. */
function longestFrames(s: string, limit?: number): Frame<ArrayState>[] {
  const chars = s.split('');
  const frames: Frame<ArrayState>[] = [];
  const seen = new Set<string>();
  let left = 0;
  let best = 0;
  let bestAt = 0;
  const snap = (right: number, note?: ArrayState['note'], bad?: number) => {
    const states: Record<number, ItemState> = { ...range(0, left - 1, 'dim'), ...range(left, right, 'active') };
    if (bad !== undefined) states[bad] = 'bad';
    frames.push({
      hold: 900,
      state: {
        rows: [
          {
            cells: chars,
            states,
            window: { from: left, to: right, label: `len ${right - left + 1}`, tone: bad !== undefined ? 'bad' : undefined },
            pointers: [
              { i: left, label: 'left', tone: 'info' },
              { i: right, label: 'right' },
            ],
          },
        ],
        panels: [{ title: 'in window', kind: 'list', items: [...seen].map((c) => `'${c}'`) }],
        stats: [
          { label: 'left', value: String(left) },
          { label: 'right', value: String(right) },
          { label: 'best', value: String(best), tone: 'ok', hint: best ? `"${s.slice(bestAt, bestAt + best)}"` : undefined },
        ],
        note,
      },
    });
  };
  for (let right = 0; right < chars.length; right++) {
    const c = chars[right];
    if (seen.has(c)) {
      snap(right, { text: `'${c}' is already in the window: shrink`, tone: 'bad' }, right);
      while (seen.has(c)) {
        seen.delete(chars[left]);
        left++;
      }
    }
    seen.add(c);
    if (right - left + 1 > best) {
      best = right - left + 1;
      bestAt = left;
    }
    snap(right);
    if (limit !== undefined && frames.length >= limit) break;
  }
  return frames;
}

/** Minimum window: shrink while still valid, recording inside the loop. */
function minFrames(): Frame<ArrayState>[] {
  const nums = [2, 3, 1, 2, 4, 3];
  const target = 7;
  const frames: Frame<ArrayState>[] = [];
  let left = 0;
  let sum = 0;
  let best = Infinity;
  const push = (right: number, note?: ArrayState['note'], tone?: 'ok') =>
    frames.push({
      hold: 850,
      state: {
        rows: [
          {
            cells: nums,
            states: { ...range(0, left - 1, 'dim'), ...range(left, right, tone === 'ok' ? 'done' : 'active') },
            window: { from: left, to: right, label: `sum ${sum}`, tone },
            pointers: [
              { i: left, label: 'left', tone: 'info' },
              { i: right, label: 'right' },
            ],
          },
        ],
        stats: [
          { label: 'target', value: `≥ ${target}` },
          { label: 'sum', value: String(sum), tone: sum >= target ? 'ok' : 'neutral' },
          { label: 'shortest', value: best === Infinity ? '-' : String(best), tone: 'ok' },
        ],
        note,
      },
    });
  for (let right = 0; right < nums.length; right++) {
    sum += nums[right];
    push(right);
    while (sum >= target) {
      best = Math.min(best, right - left + 1);
      push(right, { text: `valid, length ${right - left + 1}: record, then shrink`, tone: 'ok' }, 'ok');
      sum -= nums[left];
      left++;
    }
  }
  frames[frames.length - 1].state.note = { text: 'shortest is 2: [4, 3]', tone: 'ok' };
  return frames;
}

const RECAP: ArrayState = {
  rows: [
    { label: 'fixed', cells: NUMS, states: range(2, 4, 'found'), window: { from: 2, to: 4, label: 'size k', tone: 'ok' }, showIndex: false },
    { label: 'variable', cells: 'abcabcbb'.split(''), states: range(1, 3, 'active'), window: { from: 1, to: 3, label: 'grows, shrinks' }, showIndex: false },
  ],
  stats: [
    { label: 'Time', value: 'O(n)', tone: 'ok' },
    { label: 'Space', value: 'O(k)', hint: 'window state' },
    { label: 'Each element', value: 'in once, out once' },
  ],
};

const LONGEST = longestFrames('abcabcbb');

export default defineLesson('array', {
  slug: 'sliding-window',
  objectives: [
    { text: 'Spot problems about contiguous subarrays', step: 1 },
    { text: 'Run a fixed size window in O(n)', step: 4 },
    { text: 'Grow and shrink a variable window', step: 7 },
    { text: 'Flip the loop to find the shortest window', step: 8 },
  ],
  steps: [
    {
      label: 'The problem',
      title: 'Brute force rescans every window',
      tag: 'problem',
      body: [
        'Find the largest sum of any **3 consecutive** numbers in `[2, 1, 5, 1, 3, 2]`.',
        'The obvious way starts at every index and adds up the next k numbers. Neighbouring windows share k - 1 numbers, yet each one is added again from scratch.',
      ],
      keyIdea: 'If an answer is about a contiguous subarray or substring and brute force is O(n²) or O(n·k), think sliding window.',
      frames: bruteFrames(),
    },
    {
      label: 'Slide',
      title: 'Add one, remove one',
      tag: 'concept',
      body: [
        'Keep a window `[left, right]` and its running state, here the sum.',
        'Moving the window one step only changes two numbers: **add** the one entering on the right and **remove** the one leaving on the left.',
      ],
      keyIdea: 'Each element enters the window once and leaves once, so the total work is O(n) no matter how big k is.',
      frames: fixedFrames().slice(2, 4),
    },
    {
      label: 'Fixed run',
      title: 'A fixed window, start to finish',
      tag: 'technique',
      body: [
        'For a window of size k: add `nums[i]`. Once `i >= k - 1` the window is full, so record the answer, then remove `nums[i - k + 1]`.',
        'Watch `windowSum` change by exactly two numbers per step.',
      ],
      keyIdea: 'Fixed template: add, then if full: record and remove the element that falls off.',
      frames: fixedFrames().slice(0, -1),
    },
    {
      label: 'Answer',
      title: 'Best window: 5 + 1 + 3',
      tag: 'technique',
      body: ['The window `[2..4]` gives the best sum, **9**.', 'Brute force did 12 additions for 6 numbers. The slide did one add and at most one remove per number.'],
      keyIdea: 'O(n) time, O(1) extra space for a sum. The state can be anything you can update incrementally: a count, a set, a map.',
      frames: fixedFrames().slice(-1),
    },
    {
      label: 'Variable',
      title: 'When the size is not given',
      tag: 'concept',
      body: [
        'Longest substring without repeating characters in `"abcabcbb"`. The window has no fixed size.',
        'Move `right` forward and add each character to a set while the window stays valid.',
      ],
      keyIdea: 'Variable windows expand with right and shrink with left. The validity rule decides when to shrink.',
      frames: longestFrames('abcabcbb', 3),
    },
    {
      label: 'Shrink',
      title: 'Shrink until valid again',
      tag: 'technique',
      body: [
        'At index 3 the window would contain `a` twice. It is invalid.',
        'Move `left` forward, removing characters from the set, until the duplicate is gone. Then record the length.',
      ],
      keyIdea: 'For a longest answer: shrink while invalid, then record. The window is always valid when you measure it.',
      frames: LONGEST.slice(3, 6),
    },
    {
      label: 'Full run',
      title: 'Longest substring, every step',
      tag: 'technique',
      body: ['The window slides across the string once. `left` never moves backwards, so even with the inner loop each character is added and removed at most once.', 'The answer is **3**, for `"abc"`.'],
      keyIdea: 'Nested loops do not mean O(n²) here: both pointers only move forward, so the total is O(n).',
      frames: LONGEST,
    },
    {
      label: 'Shortest',
      title: 'Flip the loop for a minimum',
      tag: 'trade-off',
      body: [
        'Shortest subarray with sum at least 7 in `[2, 3, 1, 2, 4, 3]`.',
        'Now you shrink while the window is **still valid**, and record the answer inside the loop, because every shrink might find a shorter one.',
      ],
      keyIdea: 'Longest: shrink while invalid, record after. Shortest: shrink while valid, record inside.',
      frames: minFrames(),
    },
    {
      label: 'Recap',
      title: 'What to remember',
      tag: 'recap',
      body: [
        '- **Signal:** contiguous subarray or substring, plus longest, shortest, max sum of size k, or at most k distinct.',
        '- **Fixed:** add the new element, record when full, remove the one falling off.',
        '- **Variable:** expand right, shrink left while invalid (longest) or while valid (shortest).',
        '- **Cost:** O(n) time, because each element enters and leaves once.',
        '- **Not for:** negative numbers with a sum target. Use prefix sums there.',
      ],
      keyIdea: 'Pick fixed or variable first, then decide whether the shrink loop restores validity or tightens the answer.',
      frames: [{ state: RECAP }],
    },
  ],
});
